a<-commandArgs(TRUE);if(length(a)<2)stop("Usage: build_app.R <plsrcox_payload.rds> <out>");out<-a[2];dir.create(out,recursive=TRUE,showWarnings=FALSE);file.copy(a[1],file.path(out,"model.rds"),overwrite=TRUE);app<-c('library(shiny)','library(ggplot2)','library(scales)','payload <- readRDS("model.rds")','vars <- payload$predictors','ui <- fluidPage(titlePanel("PLS-R Cox Survival Prediction - Research Use Only"),sidebarLayout(sidebarPanel(uiOutput("inputs"),actionButton("predict","Predict")),mainPanel(tableOutput("surv_table"),plotOutput("surv_curve"))))','server <- function(input,output,session){output$inputs<-renderUI(lapply(vars,function(v)numericInput(v,v,0)));observeEvent(input$predict,{x<-as.data.frame(setNames(lapply(vars,function(v)as.numeric(input[[v]])),vars));risk<-as.numeric(predict(payload$model,newdata=as.matrix(x),type="risk"));validate(need(!is.null(payload$baseline_survival),"Baseline survival is required"));b<-payload$baseline_survival;months<-12*(1:5);s0<-approx(b$time,b$surv,xout=months,method="constant",rule=2)$y;sp<-s0^risk;z<-data.frame(Year=1:5,Survival=sp);output$surv_table<-renderTable(transform(z,Survival=percent(Survival,accuracy=.1)));output$surv_curve<-renderPlot(ggplot(z,aes(Year,Survival))+geom_line()+geom_point()+scale_y_continuous(limits=c(0,1),labels=percent)+theme_classic())})}','shinyApp(ui,server)');writeLines(app,file.path(out,"app.R"),useBytes=TRUE)
